update tg_contact
nickname = #{nickname}, username = #{username}, phone_number = #{phoneNumber}, is_mutual = #{isMutual}, is_bot = #{isBot}, is_premium = #{isPremium}, is_verified = #{isVerified}, user_type = #{userType}, bio = #{bio}, auto_reply = #{autoReply},
