UPDATE tg_contact
SET total_msg_count = CASE id
    WHEN #{it.id} THEN #{it.totalMsgCount} 
    END,
    account_sent_count = CASE id
    WHEN #{it.id} THEN #{it.accountSentCount} 
    END,
    friend_sent_count = CASE id
    WHEN #{it.id} THEN #{it.friendSentCount} 
    END,
    update_time = NOW()
WHERE id IN
#{it.id}
